import numpy as np
# run simple sim at per-frame contact state frame29: red at 115,77.9 v(-1.25,.6), white 110,79.5 v0, blue 146.5,65.6 v0
pos={'w':np.array([110.,79.5]),'r':np.array([115.,77.9]),'b':np.array([146.5,65.6])}
vel={'w':np.array([0.,0.]),'r':np.array([-1.25,.6]),'b':np.array([0.,0.])}
m={'w':10.,'r':1.,'b':.35};rad={'w':8.5,'r':7.5,'b':5.7}
ys=1.5
def norm_q(v):return np.array([v[0],v[1]*ys])
def col(a,b,e=.85):
 d=norm_q(pos[b]-pos[a]);dist=np.linalg.norm(d);R=rad[a]+rad[b]
 if dist>R or dist==0:return False
 n=d/dist;rel=norm_q(vel[b]-vel[a])@n
 if rel>0:return False
 overlap=R-dist;qa=norm_q(pos[a])-n*overlap*.5;qb=norm_q(pos[b])+n*overlap*.5;pos[a]=qa/np.array([1,ys]);pos[b]=qb/np.array([1,ys])
 va=norm_q(vel[a])@n;vb=norm_q(vel[b])@n;ma,mb=m[a],m[b]
 ua=(ma*va+mb*vb-mb*e*(va-vb))/(ma+mb);ub=(ma*va+mb*vb+ma*e*(va-vb))/(ma+mb)
 qva=norm_q(vel[a])+(ua-va)*n;qvb=norm_q(vel[b])+(ub-vb)*n
 vel[a]=qva/np.array([1,ys]);vel[b]=qvb/np.array([1,ys]);return True
for f in range(30,96):
 for k in pos:pos[k]+=vel[k]
 for k in vel:vel[k]*=.99
 if np.linalg.norm(vel['w'])<.02:vel['w']*=0
 for a,b in [('w','r'),('r','b'),('w','b')]:
  if col(a,b): print('hit',f,a,b)
 if f in [30,31,32,33,34,35,36,40,50,60,70,80,95]:print(f,{k:np.round(v,1).tolist() for k,v in pos.items()},{k:np.round(v,2).tolist() for k,v in vel.items()})
PY"
